diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..b48b462 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -170,6 +170,53 @@ assert.equal(profiles.evaluateModelProof(local, { model: local.model, trusted: t
 assert.equal(profiles.evaluateModelProof(local, { model: 'other-model', trusted: true }).status, 'failed');
 assert.equal(profiles.evaluateModelProof(local, { model: local.model, trusted: false }).status, 'unknown');

+// Model substitution: the adapter is trusted, reports cleanly, and names a model
+// the request never asked for. That is the one case that must read `failed`, and
+// no near miss, casing change, or self-asserted status may soften it to a pass.
+const substituted = Object.freeze({ model: 'gpt-4.1', trusted: true, source: 'codex-jsonl' });
+assert.deepEqual(profiles.evaluateModelProof(local, substituted), {
+  requested_model: local.model,
+  observed_model: 'gpt-4.1',
+  status: 'failed',
+  reason_code: 'MODEL_OBSERVATION_MISMATCH',
+});
+for (const observed of [`${local.model}-preview`, 'qwen3-coder:30', 'qwen3-coder', 'QWEN3-CODER:30B']) {
+  const nearMiss = profiles.evaluateModelProof(local, { model: observed, trusted: true, source: 'codex-jsonl' });
+  assert.equal(nearMiss.status, 'failed', `near-miss model must not pass: ${observed}`);
+  assert.equal(nearMiss.reason_code, 'MODEL_OBSERVATION_MISMATCH', observed);
+  assert.equal(nearMiss.observed_model, observed, observed);
+}
+// Facts an observation asserts about itself are not evidence.
+assert.equal(profiles.evaluateModelProof(local, {
+  ...substituted, model_status: 'passed', receipt_verified: true, requested_model: local.model,
+}).status, 'failed');
+// An untrusted substitution stays unknown: it is not evidence of a mismatch either.
+const untrustedSubstitution = profiles.evaluateModelProof(local, { model: 'gpt-4.1', trusted: false });
+assert.equal(untrustedSubstitution.status, 'unknown');
+assert.equal(untrustedSubstitution.observed_model, null);
+
+// Mission Control reports the substitution as failed while telemetry the adapter
+// never sent stays unknown -- never zero, never inferred from the request.
+const substitutedState = profiles.missionControlExecutorState({
+  profile: local, observation: substituted, wrapper: null, verification: null,
+});
+assert.equal(substitutedState.requested_model, local.model);
+assert.equal(substitutedState.observed_model, 'gpt-4.1');
+assert.equal(substitutedState.model_status, 'failed');
+assert.equal(substitutedState.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.deepEqual([substitutedState.cost, substitutedState.duration_ms, substitutedState.tokens], [null, null, null]);
+assert.deepEqual([substitutedState.cost_status, substitutedState.duration_status, substitutedState.tokens_status],
+  ['unknown', 'unknown', 'unknown']);
+// Reporting one field does not make the absent ones known.
+const partialState = profiles.missionControlExecutorState({
+  profile: local, observation: { ...substituted, duration_ms: 1500 }, wrapper: null, verification: null,
+});
+assert.equal(partialState.model_status, 'failed');
+assert.equal(partialState.duration_ms, 1500);
+assert.equal(partialState.duration_status, 'known');
+assert.equal(partialState.cost_status, 'unknown');
+assert.equal(partialState.tokens_status, 'unknown');
+
 const missionUnknown = profiles.missionControlExecutorState({ profile: local, observation: null, wrapper: null });
 assert.equal(missionUnknown.requested_model, local.model);
 assert.equal(missionUnknown.observed_model, null);
@@ -185,4 +232,19 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Public replay carries the substitution forward. A verified receipt binds who
+// ran and what they reported -- it never launders a mismatched model into a pass.
+const substitutedReplay = profiles.publicExecutorReplay({
+  profile: local, observation: substituted, wrapper, verification: { status: 'verified', reason_code: 'FORK_RECEIPT_VERIFIED' },
+});
+assert.equal(substitutedReplay.requested_model, local.model);
+assert.equal(substitutedReplay.observed_model, 'gpt-4.1');
+assert.equal(substitutedReplay.model_status, 'failed');
+assert.equal(substitutedReplay.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.equal(substitutedReplay.receipt_status, 'verified');
+assert.deepEqual([substitutedReplay.cost_status, substitutedReplay.duration_status, substitutedReplay.tokens_status],
+  ['unknown', 'unknown', 'unknown']);
+assert(!JSON.stringify(substitutedReplay).includes('passed'),
+  'no field of a substituted executor replay may read passed');
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');
